"use client";

import { FormEvent, useEffect, useRef, useState } from "react";
import { IntakeConfig, IntakeForm, IntakeResponses } from "./intake-ui";
import { RoutineGuide } from "./routine-guide";
import { MeetingRequest, NutritionAssessmentPanel, NutritionWorkspace, ParticipantDirectory, SessionWorkspace } from "./restored-panels";
import { AdherencePanel } from "./adherence-panel";
import { computeAdherenceAlerts } from "./adherence-alerts";
import { ParticipantHabitMatrix, TrainingDailyReview } from "./participant-adherence";
import { ParticipantWeekOverview } from "./participant-week";
import { GuideEditor } from "./guide-editor";
import { NutritionDailyReview, NutritionDailyTracker } from "./nutrition-daily";
import { ProgressMilestones } from "./progress-milestones";
import { ProfessionalTracking } from "./professional-tracking";

type Row = Record<string, unknown>;
type ViewerRole = "admin" | "professional" | "participant" | "reviewer";
type Viewer = { id: string; role: ViewerRole; name: string; email: string; status: string };
type AppData = { viewer: Viewer; professionalSpecialty?:string; preview?:{role:string;label:string;targetId?:string}; participants?: Row[]; professionals?:Row[]; administrators?:Row[]; habitDaily?:Row[]; nutritionDaily?:Row[]; adherenceOutreach?:Row[]; programs?: Row[]; programGuides?:Row[]; exercises?: Row[]; workouts?: Row[]; workoutExercises?: Row[]; content?: Row[]; sessions?: Row[]; meetingRequests?:Row[]; profile?: Row; nutrition?: Row | null; checkpoints?: Row[]; metrics?: Row[]; adherence?:Row|null; intakeQuestions?:Row[]; intakeResponses?:Row[] };
type Modal = null | "participant" | "professional" | "professional-edit" | "admin" | "admin-edit" | "program" | "workout" | "workout-edit" | "exercise" | "exercise-edit" | "attach" | "attach-edit" | "nutrition" | "content" | "session" | "meeting-review" | "participant-edit" | "intake-view" | "professional-student";

const adminNav = ["Resumen", "Participantes", "Adherencia", "Seguimiento", "Profesionales", "Programas", "Nutrición", "Contenido", "Sesiones", "Primer ingreso"];
const participantNav = ["Inicio", "Mi Semana", "Entrenamiento", "Alimentación", "Progreso", "Aprender"];
const iconMap: Record<string,string> = { Resumen:"⌂",Participantes:"◎",Adherencia:"▦",Seguimiento:"◉",Profesionales:"♙",Programas:"↗",Nutrición:"◒",Contenido:"◇",Sesiones:"▣","Primer ingreso":"?",Inicio:"⌂","Mi Semana":"☷",Entrenamiento:"↗",Alimentación:"◒",Progreso:"◎",Aprender:"◇" };
const appNow=Date.now();
const appToday=new Date(appNow);

const authHeaders = () => ({
  "Authorization": `Token ${localStorage.getItem("p90_token") || ""}`,
  "X-Branch-ID": localStorage.getItem("p90_branch") || "",
});
const API_BASE=(import.meta.env.VITE_API_BASE as string||"");
const apiUrl=(p:string)=>API_BASE+p;
function toLocalInput(value:unknown){const raw=String(value||"");if(!raw)return "";const date=new Date(raw);if(Number.isNaN(date.getTime()))return raw.slice(0,16);const pad=(n:number)=>String(n).padStart(2,"0");return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`}
async function openPdf(key:string){const res=await fetch(apiUrl(`/api/files?key=${encodeURIComponent(key)}`),{headers:authHeaders()});if(!res.ok){alert("No fue posible abrir el PDF");return}const url=URL.createObjectURL(await res.blob());window.open(url,"_blank")}

export function FunctionalApp({ initialViewer,initialData,onLogout }: { initialViewer: Viewer;initialData?:AppData;onLogout?:()=>void }) {
  const [data,setData]=useState<AppData|null>(initialData||null); const [screen,setScreen]=useState(initialViewer.role==="participant"?"Inicio":"Resumen");
  const [loading,setLoading]=useState(!initialData); const [modal,setModal]=useState<Modal>(null); const [context,setContext]=useState<Row>({});
  const [toast,setToast]=useState(""); const [error,setError]=useState(""); const [selected,setSelected]=useState<string[]>([]);
  const [previewTarget,setPreviewTarget]=useState("admin");
  const firstLoad=useRef(true);
  const activeRole=data?.viewer.role||initialViewer.role;
  const nav=activeRole==="participant"?participantNav:(activeRole==="admin"||activeRole==="reviewer")?adminNav:data?.professionalSpecialty==="nutrition"?["Resumen","Participantes","Nutrición","Seguimiento"]:["Resumen","Participantes","Seguimiento","Programas","Sesiones"];
  async function load(){setLoading(true);const params=new URLSearchParams();if(previewTarget==="coach"||previewTarget==="nutrition")params.set("viewAs",previewTarget);else if(previewTarget.startsWith("participant:")){params.set("viewAs","participant");params.set("participantId",previewTarget.slice(12))}const res=await fetch(apiUrl(`/api/app${params.size?`?${params}`:""}`),{headers:authHeaders(),cache:"no-store"});const json=await res.json();if(!res.ok)setError(json.error||"No fue posible cargar");else setData(json);setLoading(false)}
  // Initial synchronization with the durable Sites database.
  useEffect(()=>{if(firstLoad.current){firstLoad.current=false;if(initialData)return}load()},[previewTarget]);
  async function act(payload:Row){if(previewTarget.startsWith("participant:")){setError("La vista de alumno es de solo lectura.");throw new Error("solo lectura")}setError("");const res=await fetch(apiUrl("/api/app"),{method:"POST",headers:{"content-type":"application/json",...authHeaders()},body:JSON.stringify(payload)});const json=await res.json();if(!res.ok){setError(json.error||"No fue posible guardar");throw new Error(json.error)}setToast(json.message||"Guardado");setTimeout(()=>setToast(""),2600);await load();return json}
  function changePreview(value:string){setModal(null);setSelected([]);setError("");setScreen(value.startsWith("participant:")?"Inicio":"Resumen");setPreviewTarget(value)}
  function open(next:Modal,row:Row={}){setContext(row);setError("");setModal(next)}
  function nextNutrition(currentId:string){const next=(data?.participants||[]).find(x=>!x.nutrition_id&&String(x.id)!==currentId);if(next)setContext(next);else setModal(null)}
  if(loading&&!data)return <div className="app-loading"><img className="brand-wordmark loading-logo" src="/proyecto90-logo.jpg" alt="Proyecto 90" width="384" height="384"/><p>Preparando tu Proyecto 90…</p></div>;
  if(!data)return <div className="app-loading"><p>{error||"No fue posible cargar la plataforma."}</p><button className="primary" onClick={load}>Reintentar</button></div>;
  return <div className={`app-shell ${data.viewer.role==="participant"?"participant-shell":"admin-shell"} role-${data.professionalSpecialty||data.viewer.role} ${data.viewer.role==="reviewer"?"reviewer-shell":""} ${data.preview?"admin-preview-shell":""} ${data.preview?.role==="participant"?"admin-preview-participant":""}`}>
    <aside className="sidebar"><button className="brand" onClick={()=>setScreen(nav[0])}><img className="brand-wordmark" src="/proyecto90-logo.jpg" alt="Proyecto 90" width="384" height="384"/><small>90 DÍAS · GENERACIÓN 01</small></button><nav>{nav.map(x=><button key={x} className={screen===x?"active":""} onClick={()=>setScreen(x)}><span className="nav-icon">{iconMap[x]}</span>{x}</button>)}</nav><div className="sidebar-spacer"/><div className="side-quote"><span>“</span><p>No buscamos hacerlo perfecto.<br/>Buscamos hacerlo parte de tu vida.</p></div><div className="profile-mini"><span className="avatar">{initials(data.viewer.name)}</span><span><strong>{data.viewer.name}</strong><small>{roleLabel(data.viewer.role)}</small></span></div></aside>
    <main><header className="topbar"><div className="mobile-brand"><img className="brand-wordmark" src="/proyecto90-logo.jpg" alt="Proyecto 90" width="384" height="384"/></div><div className="top-actions">{initialViewer.role==="admin"&&<label className="view-as-control"><span>Ver como</span><select value={previewTarget} onChange={e=>changePreview(e.target.value)}><option value="admin">Administrador</option><option value="coach">Coach</option><option value="nutrition">Nutricionista</option>{(previewTarget==="admin"?data.participants||[]:[]).length>0&&<optgroup label="Alumnos">{(data.participants||[]).map(p=><option key={String(p.id)} value={`participant:${String(p.id)}`}>{`${p.first_name||""} ${p.last_name||""}`.trim()||String(p.email)}</option>)}</optgroup>}{previewTarget.startsWith("participant:")&&<option value={previewTarget}>{data.preview?.label||"Alumno"}</option>}</select></label>}<span className="secure-pill">● Datos guardados</span><span className="user-email">{initialViewer.email}</span><a className="logout" onClick={()=>onLogout?onLogout():window.location.reload()}>Salir</a></div></header>{data.viewer.role==="reviewer"&&<div className="reviewer-banner">Modo Revisor · Navegación de solo lectura. No puedes guardar, aprobar ni eliminar información.</div>}{data.preview&&<div className="preview-banner"><div><b>Vista de prueba: {data.preview.label}</b><span>{data.preview.role==="participant"?"Estás revisando el perfil real de este alumno.":"Como administrador puedes probar, editar y aprobar desde esta vista profesional."}</span></div><button onClick={()=>changePreview("admin")}>Volver a Administrador</button></div>}<div className="page-wrap">
      {data.viewer.role==="participant"
        ? <ParticipantArea data={data} screen={screen} setScreen={setScreen} act={act}/>
        : data.viewer.role==="professional"
          ? <ProfessionalArea data={data} screen={screen} setScreen={setScreen} open={open} act={act} selected={selected} setSelected={setSelected}/>
          : <AdminArea data={data} screen={screen} setScreen={setScreen} open={open} act={act} selected={selected} setSelected={setSelected}/>
      }
    </div><nav className="mobile-nav">{nav.slice(0,5).map(x=><button key={x} className={screen===x?"active":""} onClick={()=>setScreen(x)}><span>{iconMap[x]}</span><small>{x}</small></button>)}</nav></main>
    {modal&&<Editor key={`${modal}-${String(context.id||"")}`} modal={modal} context={context} data={data} close={()=>setModal(null)} act={act} nextNutrition={nextNutrition}/>} {toast&&<div className="toast">✓ {toast}</div>} {error&&<div className="error-toast">{error}<button onClick={()=>setError("")}>×</button></div>}
  </div>
}

function AdminArea({data,screen,setScreen,open,act,selected,setSelected}:{data:AppData;screen:string;setScreen:(x:string)=>void;open:(m:Modal,r?:Row)=>void;act:(r:Row)=>Promise<unknown>;selected:string[];setSelected:(x:string[])=>void}){
  const people=data.participants||[]; const programs=data.programs||[];
  if(screen==="Participantes")return <ParticipantDirectory people={people} programs={programs} selected={selected} setSelected={setSelected} open={open} act={act}/>;
  if(screen==="Adherencia")return <AdherencePanel people={people} records={data.habitDaily||[]} nutritionRecords={data.nutritionDaily||[]} outreach={data.adherenceOutreach||[]} act={act}/>;
  if(screen==="Seguimiento")return <ProfessionalTracking people={people} nutritionRecords={data.nutritionDaily||[]} habitRecords={data.habitDaily||[]} initialArea="nutrition" allowAreaSwitch/>;
  if(screen==="Profesionales")return <Professionals rows={data.professionals||[]} administrators={data.administrators||[]} viewerId={data.viewer.id} open={open} act={act}/>;
  if(screen==="Programas")return <ProgramManager data={data} open={open} act={act}/>;
  if(screen==="Nutrición")return <NutritionWorkspace people={people} open={open}/>;
  if(screen==="Contenido")return <ContentManager rows={data.content||[]} open={open}/>;
  if(screen==="Sesiones")return <SessionWorkspace sessions={data.sessions||[]} meetings={data.meetingRequests||[]} open={open} act={act}/>;
  if(screen==="Primer ingreso")return <IntakeConfig questions={data.intakeQuestions||[]} act={act}/>;
  const pendingNutrition=people.filter(x=>!x.nutrition_id).length; const noProgram=people.filter(x=>!x.program_id).length; const risk=countRiskyParticipants(data.habitDaily||[],data.nutritionDaily||[],people); const pendingMeetings=(data.meetingRequests||[]).filter(x=>x.status==="pending").length; const totalAttention=noProgram+pendingNutrition+risk+pendingMeetings;
  return <div className="command-dashboard"><section className="command-hero"><div><span className="eyebrow">CENTRO DE CONTROL · PROYECTO 90</span><h1>Hola, {first(data.viewer.name)}</h1><p>Tu prioridad es detectar dónde se está cayendo el proceso y actuar antes de que alguien abandone.</p></div><button className="primary" onClick={()=>open("participant")}>＋ Crear participante</button></section><section className="priority-board"><header><div><span className="eyebrow">REQUIERE ATENCIÓN HOY</span><h2>{totalAttention} {totalAttention===1?"acción pendiente":"acciones pendientes"}</h2></div><span className="priority-total">{totalAttention}</span></header><div className="priority-list"><button onClick={()=>setScreen("Participantes")}><i className="priority-icon training">↗</i><span><b>Alumnos sin programa</b><small>Necesitan una ruta de entrenamiento</small></span><strong>{noProgram}</strong></button><button onClick={()=>setScreen("Nutrición")}><i className="priority-icon nutrition">◒</i><span><b>Nutrición pendiente</b><small>Planes sin calcular o publicar</small></span><strong>{pendingNutrition}</strong></button><button onClick={()=>setScreen("Adherencia")}><i className="priority-icon risk">!</i><span><b>Adherencia en riesgo</b><small>3 días cerrados seguidos sin entreno o macros</small></span><strong>{risk}</strong></button><button onClick={()=>setScreen("Sesiones")}><i className="priority-icon meeting">▣</i><span><b>Reuniones por confirmar</b><small>Solicitudes individuales pendientes</small></span><strong>{pendingMeetings}</strong></button></div></section><section className="pulse-strip"><Metric label="Participantes" value={String(people.length)} note="Registrados"/><Metric label="Activos" value={String(people.filter(x=>x.status==="active").length)} note="En recorrido" green/><Metric label="Con programa" value={String(people.length-noProgram)} note="Ruta asignada"/><Metric label="Planes listos" value={String(people.length-pendingNutrition)} note="Nutrición publicada"/></section><div className="section-heading"><div><span className="eyebrow">SEGUIMIENTO RECIENTE</span><h2>Participantes</h2></div></div><PeopleTable rows={people.slice(0,6)} selected={[]} setSelected={()=>{}} open={open}/></div>
}

function ProfessionalArea({data,screen,setScreen,open,act,selected,setSelected}:{data:AppData;screen:string;setScreen:(x:string)=>void;open:(m:Modal,r?:Row)=>void;act:(r:Row)=>Promise<unknown>;selected:string[];setSelected:(x:string[])=>void}){
  const people=data.participants||[]; const programs=data.programs||[]; const nutrition=data.professionalSpecialty==="nutrition";
  const alerts=computeAdherenceAlerts(people,data.habitDaily||[],data.nutritionDaily||[],nutrition?["macros"]:["training"]);
  if(screen==="Seguimiento")return <><AdherencePanel people={people} records={data.habitDaily||[]} nutritionRecords={data.nutritionDaily||[]} outreach={data.adherenceOutreach||[]} act={act} mode={nutrition?"macros":"training"} canEditCells={false} canMarkContact/><div className="section-heading"><div><span className="eyebrow">DETALLE POR ALUMNO</span><h2>Cumplimiento individual</h2></div></div><ProfessionalTracking people={people} nutritionRecords={data.nutritionDaily||[]} habitRecords={data.habitDaily||[]} initialArea={nutrition?"nutrition":"training"}/></>;
  if(screen==="Participantes")return <ParticipantDirectory people={people} programs={programs} selected={selected} setSelected={setSelected} open={open} act={act} canCreate={false} canAssignProgram={!nutrition} profileModal="professional-student"/>;
  if(screen==="Programas")return <ProgramManager data={data} open={open} act={act}/>;
  if(screen==="Sesiones"&&!nutrition)return <SessionWorkspace sessions={data.sessions||[]} meetings={[]} open={open} act={act} showMeetings={false}/>;
  if(screen==="Nutrición")return <NutritionWorkspace people={people} open={open} profileModal="professional-student"/>;
  const pending=nutrition?people.filter(x=>!x.nutrition_id||x.nutrition_status!=="approved"):people.filter(x=>!x.program_id||x.training_approval_status!=="approved"); const ready=people.length-pending.length;
  return <div className="professional-dashboard"><section className="professional-hero"><div className="professional-symbol">{nutrition?"◒":"↗"}</div><div><span className="eyebrow">{nutrition?"ESPACIO DE NUTRICIÓN":"ESPACIO DE ENTRENAMIENTO"}</span><h1>{nutrition?"Decisiones claras para la vida real":"Entrenamiento seguro, claro y progresivo"}</h1><p>{nutrition?"Revisa los antecedentes, calcula los requerimientos y publica planes que cada alumno pueda comprender.":"Revisa el contexto de cada alumno, asigna la ruta correcta y aprueba lo que recibirá."}</p></div></section><section className="professional-focus"><div><span className="eyebrow">TU COLA DE APROBACIÓN</span><h2>{pending.length} {pending.length===1?"persona requiere":"personas requieren"} revisión</h2><p>{nutrition?"Abre cada ficha, revisa macros y respuestas, y aprueba el plan.":"Abre cada ficha, revisa la rutina y respuestas, y aprueba la asignación."}</p></div><div className="focus-count"><strong>{pending.length}</strong><span>pendientes</span></div></section><section className="professional-summary"><Metric label="Participantes" value={String(people.length)} note="En seguimiento"/><Metric label={nutrition?"Planes aprobados":"Rutinas aprobadas"} value={String(ready)} note="Revisión completa" green/><Metric label="Por aprobar" value={String(pending.length)} note="Prioridad actual"/><Metric label="En riesgo" value={String(alerts.riskCount)} note={nutrition?"Macros en rojo 3 días":"Entreno en rojo 3 días"}/><Metric label="Falta reportar" value={String(alerts.missingCount)} note="Sin registro +48 h"/></section><div className="section-heading"><div><span className="eyebrow">ALERTAS DE ESTA SEMANA</span><h2>{alerts.total===0?"Sin alertas operativas":`${alerts.total} ${alerts.total===1?"alumno necesita":"alumnos necesitan"} seguimiento`}</h2></div><button className="secondary" onClick={()=>setScreen("Seguimiento")}>Abrir seguimiento →</button></div><div className="section-heading"><div><span className="eyebrow">PRIORIDAD ACTUAL</span><h2>{nutrition?"Planes por aprobar":"Rutinas por aprobar"}</h2></div><button className="secondary" onClick={()=>setScreen(nutrition?"Nutrición":"Participantes")}>Ver todos los alumnos →</button></div><section className="professional-queue">{pending.slice(0,6).map(person=>{const name=`${person.first_name||""} ${person.last_name||""}`.trim()||String(person.email);return <button key={String(person.id)} onClick={()=>open("professional-student",person)}><span className="avatar">{initials(name)}</span><span><b>{name}</b><small>{nutrition?(person.nutrition_id?"Plan listo para revisar":"Plan sin calcular"):(person.program_id?"Rutina pendiente de aprobación":"Sin rutina asignada")}</small></span><strong>Abrir ficha →</strong></button>})}{pending.length===0&&<div className="professional-empty"><span>✓</span><div><b>Todo aprobado</b><p>No hay alumnos pendientes de revisión.</p></div></div>}</section></div>
}

function Professionals({rows,administrators,viewerId,open,act}:{rows:Row[];administrators:Row[];viewerId:string;open:(m:Modal,r?:Row)=>void;act:(r:Row)=>Promise<unknown>}){return <><Title eyebrow="EQUIPO PROYECTO 90" title="Profesionales y administradores" copy="Administra quién puede operar la plataforma y qué especialidad tiene cada profesional." action={<div className="inline-actions"><button className="secondary" onClick={()=>open("admin")}>＋ Administrador</button><button className="primary" onClick={()=>open("professional")}>＋ Profesional</button></div>}/><div className="access-system-note"><span>⌁</span><div><b>Acceso actual de Proyecto 90</b><p>El correo queda autorizado aquí. La autenticación sigue protegida por la cuenta de acceso asociada; una contraseña propia requiere integrar el proveedor de identidad que configurará el programador.</p></div></div><div className="section-heading"><div><span className="eyebrow">GESTIÓN TOTAL</span><h2>Administradores</h2></div><span>{administrators.length} perfiles</span></div><section className="team-management-grid">{administrators.map(x=><article key={String(x.id)}><span className="avatar">{initials(`${x.first_name||""} ${x.last_name||""}`)}</span><div><h3>{`${x.first_name||""} ${x.last_name||""}`.trim()||String(x.email)}</h3><p>{String(x.email)}</p></div><span className="audience both">Administrador</span><div className="team-actions"><button className="secondary" onClick={()=>open("admin-edit",x)}>Editar</button>{String(x.id)!==viewerId&&<button className="danger-link" onClick={()=>confirm("¿Eliminar este administrador?")&&act({action:"admin.delete",id:x.id})}>Eliminar</button>}</div></article>)}</section><div className="section-heading"><div><span className="eyebrow">EQUIPO ESPECIALISTA</span><h2>Coach y Nutrición</h2></div><span>{rows.length} perfiles</span></div>{rows.length===0?<Empty title="Aún no hay profesionales" copy="Agrega al coach y a la nutricionista con el correo que usarán para ingresar." action={<button className="primary" onClick={()=>open("professional")}>Crear profesional</button>}/>:<section className="team-management-grid">{rows.map(x=><article key={String(x.id)}><span className="avatar">{initials(`${x.first_name||""} ${x.last_name||""}`)}</span><div><h3>{`${x.first_name||""} ${x.last_name||""}`.trim()||String(x.email)}</h3><p>{String(x.email)}</p></div><span className={`audience ${x.specialty==="nutrition"?"nutrition":"coach"}`}>{x.specialty==="nutrition"?"Nutricionista":"Coach"}</span><div className="team-actions"><button className="secondary" onClick={()=>open("professional-edit",x)}>Editar</button><button className="danger-link" onClick={()=>confirm("¿Eliminar este profesional? Esta acción no elimina alumnos ni planes.")&&act({action:"professional.delete",id:x.id})}>Eliminar</button></div></article>)}</section>}</>}

function PeopleTable({rows,selected,setSelected,open}:{rows:Row[];selected:string[];setSelected:(x:string[])=>void;open:(m:Modal,r?:Row)=>void}){return <div className="table-card"><table><thead><tr><th><input type="checkbox" aria-label="Seleccionar todos" checked={rows.length>0&&selected.length===rows.length} onChange={e=>setSelected(e.target.checked?rows.map(x=>String(x.id)):[])}/></th><th>Participante</th><th>Estado</th><th>Entrenamiento</th><th>Nutrición</th><th>Adherencia</th><th></th></tr></thead><tbody>{rows.map(p=><tr key={String(p.id)}><td><input type="checkbox" checked={selected.includes(String(p.id))} onChange={e=>setSelected(e.target.checked?[...selected,String(p.id)]:selected.filter(x=>x!==p.id))}/></td><td><div className="person"><span className="avatar">{initials(`${p.first_name||""} ${p.last_name||""}`)}</span><div><b>{`${p.first_name||""} ${p.last_name||""}`.trim()||String(p.email)}</b><small>{String(p.email)}</small></div></div></td><td><Status text={String(p.status||"invited")}/></td><td>{p.program_name?String(p.program_name):<span className="muted">Sin asignar</span>}</td><td>{p.nutrition_id?<Status text="Listo"/>:<Status text="Pendiente"/>}</td><td>{p.adherence==null?<span className="muted">—</span>:<b className={Number(p.adherence)<40?"red-text":"green-text"}>{String(p.adherence)}%</b>}</td><td><div className="row-actions"><button className="row-action" onClick={()=>open("intake-view",p)}>Ficha</button><button className="row-action" onClick={()=>open("participant-edit",p)}>Editar ›</button></div></td></tr>)}</tbody></table></div>}

function ProgramManager({data,open,act}:{data:AppData;open:(m:Modal,r?:Row)=>void;act:(r:Row)=>Promise<unknown>}){
  const programs=data.programs||[],exercises=data.exercises||[];
  const [active,setActive]=useState(String(programs[0]?.id||""));
  const program=programs.find(x=>String(x.id)===active)||programs[0];
  const guide=(data.programGuides||[]).find(x=>String(x.program_id)===String(program?.id));
  const workouts=(data.workouts||[]).filter(x=>String(x.program_id)===String(program?.id));
  const links=data.workoutExercises||[];
  return <><Title eyebrow="RUTAS DE ENTRENAMIENTO" title="Programas y rutinas" copy="Coach y administración pueden crear rutas y editar cada ejercicio. Los cambios se reflejan en la rutina asignada." action={<button className="primary" onClick={()=>open("program")}>＋ Crear rutina</button>}/>
    <div className="program-tabs">{programs.map(p=><button className={String(p.id)===String(program?.id)?"active":""} key={String(p.id)} onClick={()=>setActive(String(p.id))}><b>{String(p.name)}</b><small>{(data.programGuides||[]).some(g=>String(g.program_id)===String(p.id))?"Rutina base editable":`${String(p.workout_count||0)} días`} · {String(p.participant_count||0)} alumnos</small></button>)}</div>
    {guide?<><RoutineGuide guideRow={guide} exercises={exercises} admin openExercise={row=>open("exercise-edit",row)}/><GuideEditor guideRow={guide} exercises={exercises} act={act}/></>:program&&<><div className="section-heading"><div><span className="eyebrow">{String(program.level)} · {String(program.location)}</span><h2>{String(program.name)}</h2></div><div className="inline-actions"><button className="secondary" onClick={()=>open("exercise")}>＋ Ejercicio / video</button><button className="primary" onClick={()=>open("workout",program)}>＋ Agregar día</button></div></div>{workouts.length===0?<Empty title="Aún no hay días de entrenamiento" copy="Crea el primer día y luego agrega ejercicios desde la biblioteca." action={<button className="primary" onClick={()=>open("workout",program)}>Crear primer día</button>}/>:<section className="workout-admin-grid">{workouts.map(w=><article className="workout-admin" key={String(w.id)}><div className="workout-head"><div><span className="eyebrow">MES {String(w.month)} · SEMANA {String(w.week)}</span><h3>{String(w.name)}</h3></div><div className="inline-actions"><button className="quiet-edit" onClick={()=>open("workout-edit",w)}>Editar</button><button className="secondary" onClick={()=>open("attach",w)}>＋ Ejercicio</button></div></div>{links.filter(x=>String(x.workout_id)===String(w.id)).map((x,i)=><div className="admin-exercise-row" key={String(x.id)}><span>{i+1}</span><div><b>{String(x.exercise_name)}</b><small>{String(x.sets)} × {String(x.reps)} · {String(x.rest_seconds)}s descanso</small></div>{x.youtube_url&&<a href={String(x.youtube_url)} target="_blank" rel="noreferrer">Video ↗</a>}<button className="quiet-edit" onClick={()=>open("attach-edit",x)}>Editar</button><button className="danger-link" onClick={()=>confirm("¿Retirar este ejercicio de la rutina?")&&act({action:"workout.exercise.remove",id:x.id})}>Retirar</button></div>)}</article>)}</section>}</>}
    <div className="section-heading"><div><span className="eyebrow">VIDEOS TÉCNICOS</span><h2>Biblioteca de ejercicios</h2></div><button className="secondary" onClick={()=>open("exercise")}>＋ Nuevo ejercicio</button></div>{exercises.length===0?<Empty title="Biblioteca vacía" copy="Agrega ejercicios con su video técnico."/>:<section className="exercise-library compact-library">{exercises.map(x=><article key={String(x.id)}><span className="icon-tile">▶</span><div><h3>{String(x.name)}</h3><p>{String(x.category||"Sin categoría")} · {x.youtube_url?"Con video":"Video pendiente"}</p></div><button className="secondary" onClick={()=>open("exercise-edit",x)}>Editar</button></article>)}</section>}</>;
}

function ContentManager({rows,open}:{rows:Row[];open:(m:Modal,r?:Row)=>void}){return <><Title eyebrow="BIBLIOTECA CENTRAL" title="Contenido" copy="Publica aprendizaje y videos de YouTube para que aparezcan en la sección Aprender." action={<button className="primary" onClick={()=>open("content")}>＋ Nuevo contenido</button>}/>{rows.length===0?<Empty title="Aún no hay contenido" copy="Publica el primer módulo de hábitos, nutrición o entrenamiento." action={<button className="primary" onClick={()=>open("content")}>Publicar contenido</button>}/>:<section className="content-table panel">{rows.map(x=><div className="content-row" key={String(x.id)}><span className="icon-tile">▶</span><div><h3>{String(x.title)}</h3><p>{String(x.category)} · {String(x.description||"")}</p></div>{x.video_url&&<a href={String(x.video_url)} target="_blank" rel="noreferrer">Ver video ↗</a>}<Status text="Publicado"/></div>)}</section>}</>}
function ParticipantArea({data,screen,setScreen,act}:{data:AppData;screen:string;setScreen:(x:string)=>void;act:(r:Row)=>Promise<unknown>}){if(!data.profile?.completed_at)return <IntakeForm questions={data.intakeQuestions||[]} responses={data.intakeResponses||[]} act={act}/>;const program=data.programs?.[0];const guide=data.programGuides?.[0];const workouts=data.workouts||[];const nutrition=data.nutrition;const links=data.workoutExercises||[];const adherence=Number(data.metrics?.[0]?.adherence||0);const challengeStart=data.profile?.challenge_start||program?.assigned_at;const startMs=challengeStart?new Date(`${String(challengeStart).slice(0,10)}T12:00:00Z`).getTime():appNow;const daysSince=Math.floor((appNow-startMs)/86400000);const currentDay=challengeStart?(daysSince<0?0:Math.max(1,Math.min(90,daysSince+1))):0;const progress=Math.round(currentDay/90*100);const waitingStart=currentDay===0&&Boolean(challengeStart);const trainingAdherence=Number(data.adherence?.training_pct??adherence);const macrosAdherence=Number(data.adherence?.macros_pct??0);const waterAdherence=Number(data.adherence?.water_pct??0);const totalAdherence=Number(data.adherence?.adherence??Math.round(trainingAdherence*.4+macrosAdherence*.4+waterAdherence*.2));if(screen==="Entrenamiento"&&guide)return <div className="participant-training"><RoutineGuide guideRow={guide} exercises={data.exercises||[]}/></div>;if(screen==="Entrenamiento")return <><Title eyebrow="TU RUTA ASIGNADA" title={program?String(program.name):"Entrenamiento pendiente"} copy={program?"Abre una sesión por vez y revisa cada bloque antes de comenzar.":"El equipo todavía no te asigna un programa."}/>{!program?<Empty title="Estamos preparando tu ruta" copy="Te avisaremos cuando tu programa esté asignado."/>:<section className="workout-user-grid">{workouts.map(w=><article className="workout-user" key={String(w.id)}><span className="eyebrow">MES {String(w.month)} · SEMANA {String(w.week)}</span><h2>{String(w.name)}</h2>{links.filter(x=>String(x.workout_id)===String(w.id)).map((x,i)=><div className="exercise-row" key={String(x.id)}><span className="number">{i+1}</span><div><h3>{String(x.exercise_name)}</h3><p>{String(x.sets)} × {String(x.reps)} · {String(x.rest_seconds)}s descanso</p></div>{x.youtube_url&&<a className="secondary" href={String(x.youtube_url)} target="_blank" rel="noreferrer">Ver técnica ▶</a>}</div>)}</article>)}</section>}</>;
if(screen==="Alimentación")return <><Title eyebrow="TU PLAN PERSONAL" title="Mi alimentación" copy="Objetivos aprobados y registro diario de tus resultados."/>{nutrition?<><section className="macro-grid"><Metric label="Calorías" value={`${nutrition.calories||0}`} note="kcal / día"/><Metric label="Proteínas" value={`${nutrition.protein||0} g`} note="Objetivo diario" green/><Metric label="Carbohidratos" value={`${nutrition.carbs||0} g`} note="Objetivo diario"/><Metric label="Grasas" value={`${nutrition.fats||0} g`} note="Objetivo diario"/></section><article className="panel plan-view"><div><h3>Tu plan nutricional</h3><p>{String(nutrition.notes||"Revisa tu guía y aplica los objetivos de manera flexible.")}</p></div>{nutrition.pdf_key&&<button className="primary" onClick={()=>openPdf(String(nutrition.pdf_key))}>Ver PDF</button>}</article></>:<Empty title="Plan en preparación" copy="Tu nutricionista aún no ha publicado tus objetivos."/>}<NutritionDailyTracker records={data.nutritionDaily||[]} plan={nutrition} startDate={data.profile?.challenge_start||program?.assigned_at||data.profile?.created_at} act={act}/></>;
if(screen==="Aprender")return <><Title eyebrow="APRENDER PARA NO DEPENDER" title="Aprender" copy="Contenido publicado por tu equipo."/>{(data.content||[]).length===0?<Empty title="Próximamente" copy="Los módulos aparecerán aquí cuando sean publicados."/>:<section className="learning-grid">{(data.content||[]).map(x=><article className="learn-card" key={String(x.id)}><span className="learn-cover">▶</span><div><span className="tag">{String(x.category)}</span><h3>{String(x.title)}</h3><p>{String(x.description||"")}</p>{x.video_url&&<a href={String(x.video_url)} target="_blank" rel="noreferrer">Ver contenido →</a>}</div></article>)}</section>}</>;
if(screen==="Progreso")return <><Title eyebrow="TU HISTORIA" title="Progreso" copy="Adherencia y checkpoints de tus 90 días."/><section className="stats-grid four"><Metric label="Entrenamientos" value={`${trainingAdherence}%`} note="✓ sobre días transcurridos" green/><Metric label="Macros" value={`${macrosAdherence}%`} note="Días dentro de tus objetivos"/><Metric label="Agua" value={`${Number(data.adherence?.water_pct||0)}%`} note="✓ sobre días transcurridos"/><Metric label="Adherencia total" value={`${Number(data.adherence?.adherence||0)}%`} note="40% entreno · 40% macros · 20% agua"/></section><ParticipantHabitMatrix records={data.habitDaily||[]} nutritionRecords={data.nutritionDaily||[]} plan={nutrition} startDate={data.profile?.challenge_start||program?.assigned_at||data.profile?.created_at} act={act}/></>;
if(screen==="Mi Semana")return <ParticipantWeekOverview guideRow={guide} program={program} workouts={workouts} sessions={data.sessions||[]} startDate={data.profile?.challenge_start||program?.assigned_at||data.profile?.created_at} onOpenTraining={()=>setScreen("Entrenamiento")}><MeetingRequest meetings={data.meetingRequests||[]} act={act}/></ParticipantWeekOverview>;
return <div className="participant-home"><section className="journey-hero"><div><span className="eyebrow">TU PROYECTO 90</span><h1>Hola, {first(data.viewer.name)}</h1><p>{waitingStart?`Tu desafío comienza el ${new Date(`${String(challengeStart).slice(0,10)}T12:00:00Z`).toLocaleDateString("es-CL",{day:"numeric",month:"long",year:"numeric",timeZone:"UTC"})}. Mientras tanto puedes completar tu ficha y revisar el contenido.`:"No tienes que hacerlo perfecto. Hoy solo tienes que seguir apareciendo."}</p></div><div className="journey-day"><span>{waitingStart?"INICIA":"DÍA"}</span><strong>{waitingStart?"—":currentDay}</strong><small>{waitingStart?"PRONTO":"DE 90"}</small></div><div className="journey-track"><i style={{width:`${progress}%`}}/><span>Inicio</span><b>{progress}% del recorrido</b><span>Día 90</span></div></section><ProgressMilestones person={{...(data.profile||{}),...(data.adherence||{})}} checkpoints={data.checkpoints||[]} currentDay={currentDay} editable={!data.preview} act={act}/><section className="today-command"><header><div><span className="eyebrow">HOY · UNA ACCIÓN A LA VEZ</span><h2>¿Qué hago ahora?</h2></div><span className="today-date">{appToday.toLocaleDateString("es-CL",{weekday:"long",day:"numeric",month:"long"})}</span></header><div className="today-actions"><article className="today-primary"><span className="today-number">01</span><div><small>ENTRENAMIENTO</small><h3>{workouts[0]?String(workouts[0].name):"Tu ruta está en preparación"}</h3><p>{program?String(program.name):"El equipo te asignará un programa."}</p></div><button className="primary" onClick={()=>setScreen("Entrenamiento")}>{program?"Abrir mi entrenamiento":"Ver estado"} →</button></article><article><span className="today-number">02</span><div><small>ALIMENTACIÓN</small><h3>{nutrition?`${nutrition.calories||0} kcal · ${nutrition.protein||0} g proteína`:"Plan en preparación"}</h3><p>{nutrition?"Tus objetivos diarios están aprobados.":"La nutricionista está revisando tu información."}</p></div><button className="secondary" onClick={()=>setScreen("Alimentación")}>Ver mi plan →</button></article></div></section><section className="home-lower"><article className="adherence-story"><header><div><span className="eyebrow">ADHERENCIA</span><h2>Tu constancia, sin castigos</h2></div><strong>{totalAdherence}%</strong></header><p>El número no te juzga. Nos ayuda a detectar dónde necesitas apoyo para volver al plan.</p><div className="adherence-row"><span>Entrenamiento</span><i><b style={{width:`${trainingAdherence}%`}}/></i><strong>{trainingAdherence}%</strong></div><div className="adherence-row"><span>Macros</span><i><b style={{width:`${macrosAdherence}%`}}/></i><strong>{macrosAdherence}%</strong></div><div className="adherence-row"><span>Agua</span><i><b style={{width:`${waterAdherence}%`}}/></i><strong>{waterAdherence}%</strong></div><button className="text-action" onClick={()=>setScreen("Progreso")}>Ver mi progreso completo →</button></article><article className="support-card"><span className="eyebrow">ACOMPAÑAMIENTO</span><h2>{data.sessions?.[0]?String(data.sessions[0].title):"Tu equipo está contigo"}</h2><p>{data.sessions?.[0]?new Date(String(data.sessions[0].starts_at)).toLocaleString("es-CL"):"Las próximas sesiones y apoyos aparecerán aquí."}</p><button className="secondary" onClick={()=>setScreen("Mi Semana")}>Ver mi semana →</button></article></section></div>}

function Editor({modal,context,data,close,act,nextNutrition}:{modal:Exclude<Modal,null>;context:Row;data:AppData;close:()=>void;act:(x:Row)=>Promise<unknown>;nextNutrition:(id:string)=>void}){const [saving,setSaving]=useState(false);const [fileKey,setFileKey]=useState(String(context.pdf_key||""));const [uploading,setUploading]=useState(false);useEffect(()=>setFileKey(String(context.pdf_key||"")),[context.id,context.pdf_key]);if(modal==="professional-student")return <ProfessionalStudentFile context={context} data={data} close={close} act={act}/>;if(modal==="intake-view")return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&close()}><section className="editor-modal response-modal"><div className="modal-head"><div><span className="eyebrow">FICHA DEL ALUMNO</span><h2>Formulario y seguimiento</h2></div><button onClick={close}>×</button></div><div className="participant-file-summary"><span><small>Día actual</small><b>{context.assigned_at?`${Math.max(1,Math.min(90,Math.floor((appNow-new Date(String(context.assigned_at)).getTime())/86400000)+1))}/90`:"—"}</b></span><span><small>Peso inicial</small><b>{context.weight?`${context.weight} kg`:"No informado"}</b></span><span><small>Último peso</small><b>{context.latest_weight?`${context.latest_weight} kg`:"No informado"}</b></span><span><small>Programa</small><b>{String(context.program_name||"Sin asignar")}</b></span></div><ProgressMilestones person={context} currentDay={Number(context.adherence_elapsed_days||0)}/><IntakeResponses participant={context} questions={data.intakeQuestions||[]} responses={data.intakeResponses||[]}/></section></div>;async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setSaving(true);const form=new FormData(e.currentTarget);const values=Object.fromEntries(form.entries());const editing=["participant-edit","professional-edit","admin-edit","workout-edit","exercise-edit","attach-edit"].includes(modal)||(modal==="session"&&Boolean(context.id))||modal==="meeting-review";const action=modal==="session"&&context.id?"session.update":actionFor(modal);try{await act({...values,action,...(editing?{id:context.id}:{}) ,...(modal==="workout"?{programId:context.id}:{}),...(modal==="attach"?{workoutId:context.id}:{}),...(modal==="nutrition"?{userId:context.id,pdfKey:fileKey}:{})});if(modal==="nutrition")nextNutrition(String(context.id));else close()}finally{setSaving(false)}}async function upload(file:File){setUploading(true);try{const fd=new FormData();fd.set("file",file);fd.set("userId",String(context.id));const r=await fetch(apiUrl("/api/files"),{method:"POST",headers:authHeaders(),body:fd});const j=await r.json();if(!r.ok){alert(j.error||"No fue posible subir el PDF");return}setFileKey(j.key)}finally{setUploading(false)}}return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><section className="editor-modal"><div className="modal-head"><div><span className="eyebrow">EDITOR PROYECTO 90</span><h2>{modalTitle(modal,context)}</h2></div><button onClick={close}>×</button></div><form onSubmit={submit}><Fields modal={modal} context={context} data={data}/>{modal==="nutrition"&&(data.viewer.role==="admin"&&String(context.nutrition_status||"")==="approved"?<label className="upload">Guía nutricional PDF (admin)<input type="file" accept="application/pdf" onChange={e=>e.target.files?.[0]&&upload(e.target.files[0])}/><span>{uploading?"Subiendo…":fileKey?"✓ PDF cargado":"＋ Adjuntar guía (máx. 10 MB)"}</span></label>:<p className="modal-context">{String(context.nutrition_status||"")==="approved"?"La guía PDF la adjunta el administrador.":"Primero aprueba el plan; después el administrador adjunta la guía PDF."}</p>)}<div className="editor-actions"><button type="button" className="secondary" onClick={close}>Cancelar</button><button className="primary" disabled={saving||uploading}>{saving?"Guardando…":modal==="nutrition"?"Guardar plan":"Guardar cambios"}</button></div></form></section></div>}

function ProfessionalStudentFile({context,data,close,act}:{context:Row;data:AppData;close:()=>void;act:(x:Row)=>Promise<unknown>}){
  const [programChoice,setProgramChoice]=useState(String(context.program_id||""));
  const nutrition=data.professionalSpecialty==="nutrition"; const name=`${context.first_name||""} ${context.last_name||""}`.trim()||String(context.email||"Alumno");
  const approved=nutrition?String(context.nutrition_status)==="approved":String(context.training_approval_status)==="approved";
  const guide=(data.programGuides||[]).find(x=>String(x.program_id)===String(context.program_id));
  const workouts=(data.workouts||[]).filter(x=>String(x.program_id)===String(context.program_id));
  const weight=Number(context.weight||0), calories=Number(context.calories||0); let referenceWeight=weight;try{referenceWeight=Number((JSON.parse(String(context.nutrition_assessment||"{}")) as {referenceWeight?:number}).referenceWeight||weight)}catch{/* Fall back to current weight. */}
  const macros=[{name:"Proteínas",grams:Number(context.protein||0),factor:4},{name:"Carbohidratos",grams:Number(context.carbs||0),factor:4},{name:"Grasas / lípidos",grams:Number(context.fats||0),factor:9}];
  const canApprove=nutrition?Boolean(context.nutrition_id):Boolean(context.program_id);
  return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&close()}><section className="editor-modal professional-student-modal"><div className="modal-head"><div><span className="eyebrow">{nutrition?"EXPEDIENTE NUTRICIONAL":"EXPEDIENTE DE ENTRENAMIENTO"}</span><h2>{name}</h2><p>{String(context.email||"")}</p></div><button onClick={close}>×</button></div>
    <div className="professional-file-summary"><span><small>Peso inicial</small><b>{weight?`${weight} kg`:"—"}</b></span><span><small>Último peso</small><b>{context.latest_weight?`${context.latest_weight} kg`:"—"}</b></span><span><small>{nutrition?"Plan nutricional":"Rutina asignada"}</small><b>{nutrition?(context.nutrition_id?"Calculado":"Sin calcular"):String(context.program_name||"Sin asignar")}</b></span><span><small>Aprobación profesional</small><b className={approved?"approved-text":"pending-text"}>{approved?"✓ Aprobado":"Pendiente"}</b></span></div><ProgressMilestones person={context} currentDay={Number(context.adherence_elapsed_days||0)}/>
    {!nutrition&&<><section className="professional-file-section professional-intake"><div className="professional-file-heading"><div><span className="eyebrow">PASO 1 · ANTECEDENTES DEL FORMULARIO</span><h3>Revisa las respuestas del alumno</h3><p>Visibilidad: Coach + Ambos.</p></div></div><IntakeResponses participant={context} questions={data.intakeQuestions||[]} responses={data.intakeResponses||[]}/></section><TrainingDailyReview records={data.habitDaily||[]} person={context}/></>}
    {nutrition&&<><NutritionAssessmentPanel person={context}/><NutritionDailyReview records={data.nutritionDaily||[]} person={context}/></>}
    {nutrition?<section className="professional-file-section"><div className="professional-file-heading"><div><span className="eyebrow">DISTRIBUCIÓN DIARIA</span><h3>Macronutrientes calculados</h3></div><strong>{calories?`${calories} kcal`:"Sin calcular"}</strong></div>{context.nutrition_id?<div className="professional-macro-table"><div className="professional-macro-row macro-head"><span>Macronutriente</span><span>% energía</span><span>Energía</span><span>Gramos</span><span>g/kg ref.</span></div>{macros.map(m=>{const energy=m.grams*m.factor;return <div className="professional-macro-row" key={m.name}><b>{m.name}</b><span>{calories?`${Math.round(energy/calories*100)}%`:"—"}</span><span>{m.grams?`${energy} kcal`:"—"}</span><span>{m.grams?`${m.grams} g`:"—"}</span><span>{referenceWeight&&m.grams?(m.grams/referenceWeight).toFixed(2):"—"}</span></div>})}</div>:<div className="professional-file-empty"><b>Plan aún no calculado</b><p>Completa los macros desde la vista de Nutrición antes de aprobar.</p></div>}</section>
    :<section className="professional-file-section routine-file-section"><div className="professional-file-heading"><div><span className="eyebrow">PASO 2 · ASIGNACIÓN DE RUTINA</span><h3>{String(context.program_name||"Rutina sin asignar")}</h3></div></div><div className="coach-program-assignment"><label>Rutina para este alumno<select value={programChoice} onChange={e=>setProgramChoice(e.target.value)}><option value="">Selecciona una rutina…</option>{(data.programs||[]).map(program=><option key={String(program.id)} value={String(program.id)}>{String(program.name)}</option>)}</select></label><button className="primary" disabled={!programChoice||programChoice===String(context.program_id||"")} onClick={async()=>{await act({action:"program.assign",userId:context.id,programId:programChoice});close()}}>{context.program_id?"Cambiar rutina":"Asignar rutina"}</button></div>{guide?<RoutineGuide guideRow={guide} exercises={data.exercises||[]}/>:workouts.length?<div className="fallback-workouts">{workouts.map(x=><article key={String(x.id)}><b>{String(x.title||x.name||"Sesión")}</b><p>{String(x.description||"Rutina asignada al alumno.")}</p></article>)}</div>:<div className="professional-file-empty"><b>Sin rutina asignada</b><p>Después de revisar sus respuestas, selecciona la rutina correspondiente.</p></div>}</section>}
    {nutrition&&<section className="professional-file-section professional-intake"><div className="professional-file-heading"><div><span className="eyebrow">ANTECEDENTES DEL FORMULARIO</span><h3>Preguntas y respuestas del alumno</h3><p>Visibilidad: Nutrición + Ambos.</p></div></div><IntakeResponses participant={context} questions={data.intakeQuestions||[]} responses={data.intakeResponses||[]}/></section>}
    <div className="professional-approval-bar"><div><span className={`approval-dot ${approved?"approved":""}`}>{approved?"✓":"!"}</span><span><b>{approved?"Asignación aprobada":"Revisión profesional pendiente"}</b><small>{approved?"El alumno puede guiarse por esta versión.":"Revisa la ficha completa antes de aprobar."}</small></span></div>{!approved&&<button className="primary" disabled={!canApprove} onClick={async()=>{await act({action:nutrition?"nutrition.review":"training.review",userId:context.id});close()}}>{canApprove?nutrition?"Aprobar plan nutricional":"Aprobar rutina asignada":nutrition?"Primero calcula el plan":"Primero asigna una rutina"}</button>}</div>
  </section></div>
}

function Fields({modal,context,data}:{modal:Exclude<Modal,null>;context:Row;data:AppData}){if(modal==="participant"||modal==="participant-edit")return <><div className="access-explainer"><b>Acceso del participante</b><p>No se crea una contraseña aquí. Debe entrar con este mismo correo y la contraseña de su cuenta de acceso. Si todavía no tiene cuenta, deberá crearla con este correo.</p></div><div className="form-grid two"><Field n="firstName" l="Nombre" d={context.first_name} required/><Field n="lastName" l="Apellido" d={context.last_name}/><Field n="email" l="Correo de acceso a 90 días" d={context.email} type="email" disabled={modal==="participant-edit"} required/><Field n="city" l="Ciudad" d={context.city}/><Field n="objective" l="Objetivo principal" d={context.objective}/><Field n="trainingDays" l="Días disponibles" d={context.training_days||3} type="number"/></div><div className="form-grid two"><Select n="location" l="Lugar" d={context.preferred_location} opts={["Casa","Gimnasio","Ambos"]}/><Select n="activityLevel" l="Actividad" d={context.activity_level} opts={["Sedentario","Mixto","Activo"]}/>{modal==="participant"&&<Select n="programId" l="Programa inicial" opts={["",...(data.programs||[]).map(x=>String(x.id))]} labels={["Asignar después",...(data.programs||[]).map(x=>String(x.name))]}/>} {modal==="participant-edit"&&<Select n="status" l="Estado" d={context.status} opts={["invited","onboarding","review","configuration","active","finished"]}/>}</div>{modal==="participant-edit"&&<div className="access-explainer"><b>Adherencia calculada automáticamente</b><p>Los porcentajes se alimentan de los registros diarios del alumno y no se editan manualmente.</p></div>}<Area n="restrictions" l="Restricciones alimentarias" d={context.dietary_restrictions}/><Area n="motivation" l="¿Por qué quiere hacer Proyecto 90?" d={context.motivation}/> </>;
if(modal==="professional"||modal==="professional-edit")return <><div className="access-explainer"><b>Acceso profesional</b><p>Autoriza el correo que utilizará el profesional. Su especialidad define las respuestas, alumnos y aprobaciones disponibles en su panel.</p></div><div className="form-grid two"><Field n="firstName" l="Nombre" d={context.first_name} required/><Field n="lastName" l="Apellido" d={context.last_name}/><Field n="email" l="Correo autorizado" d={context.email} type="email" required/><Select n="specialty" l="Especialidad" d={context.specialty||"coach"} opts={["coach","nutrition"]} labels={["Coach / preparador físico","Nutricionista"]}/>{modal==="professional-edit"&&<Select n="status" l="Estado" d={context.status||"active"} opts={["active","inactive"]} labels={["Activo","Inactivo"]}/>}</div></>;
if(modal==="admin"||modal==="admin-edit")return <><div className="access-explainer"><b>Acceso administrador</b><p>Este perfil podrá ver y gestionar administradores, profesionales, alumnos, programas, nutrición y adherencia.</p></div><div className="form-grid two"><Field n="firstName" l="Nombre" d={context.first_name} required/><Field n="lastName" l="Apellido" d={context.last_name}/><Field n="email" l="Correo autorizado" d={context.email} type="email" required/>{modal==="admin-edit"&&<Select n="status" l="Estado" d={context.status||"active"} opts={["active","inactive"]} labels={["Activo","Inactivo"]}/>}</div></>;
if(modal==="program")return <><Field n="name" l="Nombre del programa" placeholder="Ej. Casa Avanzado" required/><div className="form-grid two"><Select n="level" l="Nivel" opts={["Inicial","Intermedio","Avanzado"]}/><Select n="location" l="Lugar" opts={["Casa","Gimnasio","Ambos"]}/></div></>;
if(modal==="workout"||modal==="workout-edit")return <><p className="modal-context">{modal==="workout"?<>Programa: <b>{String(context.name)}</b></>:"Edita el nombre y la ubicación temporal de esta rutina."}</p><Field n="name" l="Nombre de la rutina" d={context.name} placeholder="Ej. Rutina A · Fuerza base" required/><div className="form-grid two"><Field n="month" l="Mes" type="number" d={context.month||1}/><Field n="week" l="Semana" type="number" d={context.week||1}/></div></>;
if(modal==="exercise"||modal==="exercise-edit")return <><div className="form-grid two"><Field n="name" l="Nombre del ejercicio" d={context.name} required/><Field n="youtubeUrl" l="Video YouTube no listado" d={context.youtube_url} placeholder="https://youtube.com/watch?v=…" type="url"/><Field n="category" l="Categoría" d={context.category} placeholder="Piernas, empuje…"/><Select n="level" l="Nivel" d={context.level} opts={["Inicial","Intermedio","Avanzado"]}/></div><Area n="description" l="Descripción" d={context.description}/><Area n="technique" l="Técnica" d={context.technique}/><Area n="commonErrors" l="Errores frecuentes" d={context.common_errors}/><div className="form-grid two"><Field n="regression" l="Regresión" d={context.regression}/><Field n="progression" l="Progresión" d={context.progression}/></div></>;
if(modal==="attach"||modal==="attach-edit")return <><p className="modal-context">{modal==="attach"?<>Rutina: <b>{String(context.name)}</b></>:<>Ejercicio: <b>{String(context.exercise_name)}</b></>}</p>{modal==="attach"&&<Select n="exerciseId" l="Ejercicio de la biblioteca" opts={(data.exercises||[]).map(x=>String(x.id))} labels={(data.exercises||[]).map(x=>String(x.name))}/>}<div className="form-grid three"><Field n="sets" l="Series" type="number" d={context.sets||3}/><Field n="reps" l="Repeticiones" d={context.reps||10}/><Field n="restSeconds" l="Descanso (seg)" type="number" d={context.rest_seconds||60}/></div><Area n="notes" l="Notas para el alumno" d={context.notes}/></>;
if(modal==="nutrition")return <><p className="modal-context"><b>{`${context.first_name||""} ${context.last_name||""}`}</b> · {String(context.objective||"Sin objetivo")} · Peso: <b>{context.weight?`${context.weight} kg`:"No informado"}</b></p><ProgressMilestones person={context} currentDay={Number(context.adherence_elapsed_days||0)}/><NutritionAssessmentPanel person={context}/><NutritionDailyReview records={data.nutritionDaily||[]} person={context}/><div className="form-grid four"><Field n="calories" l="Calorías sugeridas" type="number" d={context.calories}/><Field n="protein" l="Proteína (g)" type="number" d={context.protein}/><Field n="carbs" l="Carbohidratos (g)" type="number" d={context.carbs}/><Field n="fats" l="Grasas / lípidos (g)" type="number" d={context.fats}/></div><Select n="status" l="Estado del plan" d={context.nutrition_status||"pending_review"} opts={["pending_review","approved","rejected"]} labels={["Por revisar","Aprobar y publicar","Rechazar / devolver"]}/><Area n="notes" l="Comentario profesional" d={context.nutrition_notes}/><Field n="reviewDate" l="Fecha de revisión" type="date" d={context.review_date}/></>;
if(modal==="content")return <><div className="form-grid two"><Field n="title" l="Título" required/><Select n="category" l="Categoría" opts={["Hábitos","Nutrición","Entrenamiento","Sesiones"]}/></div><Area n="description" l="Descripción"/><Field n="videoUrl" l="Video YouTube no listado" type="url"/><div className="form-grid two"><Field n="position" l="Orden" type="number" d="1"/><Field n="publishAt" l="Publicar desde" type="datetime-local"/></div></>;
if(modal==="meeting-review")return <><p className="modal-context"><b>{`${context.first_name||""} ${context.last_name||""}`}</b> · {String(context.email||"")}</p><p className="modal-context">Horario solicitado: {new Date(String(context.requested_at)).toLocaleString("es-CL")}</p><Select n="status" l="Decisión" d={context.status==="pending"?"confirmed":context.status} opts={["confirmed","rescheduled","rejected"]} labels={["Aprobar","Reprogramar","Rechazar"]}/><Field n="startsAt" l="Fecha y hora definitiva" type="datetime-local" d={context.starts_at||context.requested_at} required/><Field n="meetingLink" l="Enlace Google Meet o Zoom (obligatorio al aprobar)" type="url" d={context.meeting_link}/><Area n="adminNote" l="Nota para el alumno" d={context.admin_note}/></>;
return <><Field n="title" l="Nombre de la sesión" d={context.title} required/><div className="form-grid two"><Field n="professional" l="Profesional" d={context.professional}/><Field n="startsAt" l="Fecha y hora" type="datetime-local" d={context.starts_at} required/></div><Field n="link" l="Enlace en vivo" type="url" d={context.link}/><Field n="recordingUrl" l="Grabación YouTube" type="url" d={context.recording_url}/></>}

function Title({eyebrow,title,copy,action}:{eyebrow:string;title:string;copy:string;action?:React.ReactNode}){return <div className="admin-title"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{copy}</p></div>{action}</div>}
function Metric({label,value,note,green=false}:{label:string;value:string;note:string;green?:boolean}){return <article className={`metric ${green?"green":""}`}><div className="metric-head"><span className="metric-icon">{green?"✓":"◎"}</span><span>{label}</span></div><strong>{value}</strong><small>{note}</small></article>}
function Empty({title,copy,action}:{title:string;copy:string;action?:React.ReactNode}){return <article className="empty-state"><span className="icon-tile green">＋</span><h2>{title}</h2><p>{copy}</p>{action}</article>}
function Status({text}:{text:string}){const labels:Record<string,string>={invited:"Invitado",onboarding:"Onboarding",review:"En revisión",configuration:"Configuración",active:"Activo",finished:"Finalizado"};const shown=labels[text]||text;return <span className={`status ${text.toLowerCase().replace(/\s/g,"-")}`}>{shown}</span>}
function Field({n,l,d="",type="text",placeholder="",required=false,disabled=false}:{n:string;l:string;d?:unknown;type?:string;placeholder?:string;required?:boolean;disabled?:boolean}){const shown=type==="datetime-local"?toLocalInput(d):String(d||"");return <label>{l}<input name={n} defaultValue={shown} type={type} placeholder={placeholder} required={required} disabled={disabled}/></label>}
function Area({n,l,d=""}:{n:string;l:string;d?:unknown}){return <label>{l}<textarea name={n} defaultValue={String(d||"")}/></label>}
function Select({n,l,d="",opts,labels}:{n:string;l:string;d?:unknown;opts:string[];labels?:string[]}){return <label>{l}<select name={n} defaultValue={String(d||opts[0]||"")}>{opts.map((x,i)=><option value={x} key={x}>{labels?.[i]||x}</option>)}</select></label>}
function actionFor(m:Exclude<Modal,null>){return ({participant:"participant.create",professional:"professional.create","professional-edit":"professional.update",admin:"admin.create","admin-edit":"admin.update","participant-edit":"participant.update",program:"program.create",workout:"workout.create","workout-edit":"workout.update",exercise:"exercise.create","exercise-edit":"exercise.update",attach:"workout.exercise.add","attach-edit":"workout.exercise.update",nutrition:"nutrition.save",content:"content.create",session:"session.create","meeting-review":"meeting.review"} as Record<string,string>)[m]}
function modalTitle(m:Exclude<Modal,null>,c:Row){return ({participant:"Crear participante",professional:"Crear profesional","professional-edit":"Editar profesional",admin:"Crear administrador","admin-edit":"Editar administrador","participant-edit":"Editar participante",program:"Crear programa",workout:"Agregar rutina","workout-edit":"Editar rutina",exercise:"Agregar ejercicio y video","exercise-edit":"Editar ejercicio y video",attach:`Agregar ejercicio a ${String(c.name||"rutina")}`,"attach-edit":`Editar ${String(c.exercise_name||"ejercicio")}`,nutrition:"Editar nutrición",content:"Publicar contenido",session:c.id?"Editar sesión":"Crear sesión","meeting-review":"Gestionar reunión individual"} as Record<string,string>)[m]}
function initials(n:string){return n.split(" ").filter(Boolean).slice(0,2).map(x=>x[0]?.toUpperCase()).join("")||"90"} function first(n:string){return n.split(" ")[0]||"Moya"} function roleLabel(r:string){return r==="admin"?"Administrador":r==="professional"?"Profesional":r==="reviewer"?"Revisor":"Participante"}
function countRiskyParticipants(records:Row[],nutrition:Row[]=[],people:Row[]=[]){const today=new Intl.DateTimeFormat("en-CA",{timeZone:"America/Santiago",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date()),now=new Date(`${today}T12:00:00Z`),weekday=now.getUTCDay(),monday=new Date(now.getTime()-(weekday===0?6:weekday-1)*86400000).toISOString().slice(0,10);const calculated=nutrition.flatMap(row=>{const person=people.find(item=>String(item.id)===String(row.user_id)),targetCalories=Number(person?.calories||0),targetProtein=Number(person?.protein||0);if(!targetCalories||!targetProtein)return [];return [{user_id:row.user_id,habit:"macros",habit_date:row.log_date,status:Number(row.calories)>targetCalories*1.1||Number(row.protein)<targetProtein*.9?"missed":"met"}]});const all=[...records.filter(row=>row.habit!=="macros"),...calculated],lookup=new Map(all.map(row=>[`${row.user_id}:${row.habit}:${row.habit_date}`,row.status])),risky=new Set<string>();for(const person of people){const id=String(person.id),start=String(person.challenge_start||person.assigned_at||person.created_at||monday).slice(0,10);for(const habit of ["training","macros"]){let streak=0;for(let cursor=new Date(`${monday}T12:00:00Z`);cursor.toISOString().slice(0,10)<today;cursor=new Date(cursor.getTime()+86400000)){const date=cursor.toISOString().slice(0,10);if(date<start)continue;streak=lookup.get(`${id}:${habit}:${date}`)==="missed"?streak+1:0;if(streak>=3){risky.add(id);break}}}}return risky.size}
